// spec: specs/guides-videos.md (2.8–2.10) · кейс: .qa/tests/guides-videos/GUIDES-25.md
// seed: tests/seed.admin.spec.ts (admin, сессия ../auth/admin.json; файл не перезаписывается, из аккаунта не выходим) ·
// прод, только чтение: не-GET обрываются, SW выключен.
// Тикет #359741 «מה רצוי»: «רק מנהל (admin) יכול לראות אותם: קישור בתפריט, קישור בפוטר ועמוד /guides».
// Места пунктов — как на проде при проведении (2026-11-10): шапка/меню — сразу после калькулятора; футер — между
// калькулятором и «שאלות ותשובות».
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, LOAD, NAV, GUIDES, dismissPopups, openMobileMenu, openGuides, linkTexts, expectNext,
  CALC, PUBLISH, FAQ, MENU_GUIDES, FOOTER_GUIDES,
} from './guides.helpers';

test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

const H1 = 'מדריכי וידאו';

test.describe('Гайды видит админ (#359741)', () => {
  test('admin: «מדריכים» в шапке после калькулятора, «מדריכי וידאו» в футере, переход открывает /guides, перезагрузка остаётся на /guides #359741 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/');
    const banner = page.getByRole('banner');
    const headerLink = banner.getByRole('link', { name: MENU_GUIDES, exact: true });
    await expect(headerLink, 'пункт «מדריכים» в шапке').toBeVisible(LOAD);
    await expect(headerLink).toHaveAttribute('href', '/guides');
    const header = await linkTexts(banner);
    expectNext(header, CALC, MENU_GUIDES, 'шапка');
    expectNext(header, MENU_GUIDES, PUBLISH, 'шапка');

    const footer = page.getByRole('contentinfo');
    const footerLink = footer.getByRole('link', { name: FOOTER_GUIDES, exact: true });
    await expect(footerLink, 'ссылка «מדריכי וידאו» в футере').toHaveAttribute('href', '/guides', LOAD);
    const foot = await linkTexts(footer);
    expectNext(foot, CALC, FOOTER_GUIDES, 'футер');
    expectNext(foot, FOOTER_GUIDES, FAQ, 'футер');

    await headerLink.click();
    await page.waitForURL((u) => u.pathname === '/guides', NAV);
    await expect(page.getByRole('heading', { level: 1, name: H1 }), 'h1 «מדריכי וידאו»').toBeVisible(LOAD);
    await expect(page.getByRole('article'), 'карточки гайдов').toHaveCount(GUIDES.length, LOAD);
    await expect(page.locator('video'), 'видео гайдов').toHaveCount(GUIDES.length);

    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: H1 }), 'после перезагрузки — /guides').toBeVisible(LOAD);
    await expect(page.getByRole('article')).toHaveCount(GUIDES.length, LOAD);
    expect(new URL(page.url()).pathname, 'перезагрузка не уводит с /guides').toBe('/guides');
  });

  test('admin: ссылка «מדריכי וידאו» в футере открывает /guides #359741 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/calculator');
    const link = page.getByRole('contentinfo').getByRole('link', { name: FOOTER_GUIDES, exact: true });
    await expect(link, 'ссылка в футере').toBeVisible(LOAD);
    await link.click();
    await page.waitForURL((u) => u.pathname === '/guides', NAV);
    await expect(page.getByRole('heading', { level: 1, name: H1 })).toBeVisible(LOAD);
  });

  test('admin: в мобильном меню «מדריכים» 5-м пунктом (после калькулятора), открывает /guides #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/');
    const menu = await openMobileMenu(page);
    const items = menu.getByRole('link');
    await expect(items.nth(3), '4-й пункт').toHaveText(CALC);
    await expect(items.nth(4), '5-й пункт').toHaveText(MENU_GUIDES, LOAD);
    await expect(items.nth(4)).toHaveAttribute('href', '/guides');
    await expect(items.nth(5), '6-й пункт').toHaveText(PUBLISH);

    await items.nth(4).click();
    await page.waitForURL((u) => u.pathname === '/guides', NAV);
    await expect(page.getByRole('heading', { level: 1, name: H1 })).toBeVisible(LOAD);
  });

  test('admin: прямой /guides открывает страницу с 5 видео #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await openGuides(page);
    await expect(page.getByRole('heading', { level: 1, name: H1 })).toBeVisible();
    expect(new URL(page.url()).pathname).toBe('/guides');
  });
});
